package org.example.Employee;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;@Configurationpublic class AppConfig {    @Bean    public Salary salary() {        return new Salary(30000, 5000, 3000);    }    @Bean    public Address address() {        return new Address("Ghaziabad", "Uttar Pradesh");    }    @Bean    public Department department() {        return new Department(101, "IT");    }    @Bean    public Employee employee(Salary salary,                             Address address,                             Department department) {        return new Employee(1, "Aman",                salary, address, department);    }}